using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.IO.Compression;using System.Xml;using System.Globalization;using System.Web.Script.Serialization;
namespace Tvxd.Meps {
 public sealed class P {public double x,y;public P(){}public P(double x,double y){this.x=x;this.y=y;}}
 public sealed class Meta {public int schema=1;public string id=Guid.NewGuid().ToString("N"),kind,code,name,level,function;public double? watts;}
 public sealed class Row {public string Handle{get;set;}public string Id{get;set;}public string Code{get;set;}public string Name{get;set;}public string Level{get;set;}public string Kind{get;set;}public string Room{get;set;}public double? AreaM2{get;set;}public double? Watts{get;set;}public string Issue{get;set;}public P[] polygon;public P point;}
 public sealed class Snapshot {public List<Row> rooms=new List<Row>(),devices=new List<Row>();public List<string> issues=new List<string>();}
 public static class Core {
  public static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  public static bool Finite(double x){return !double.IsNaN(x)&&!double.IsInfinity(x)&&Math.Abs(x)<=1e12;}
  public static void Validate(Meta m){if(m==null||m.schema!=1||string.IsNullOrWhiteSpace(m.id)||!new[]{"ROOM","LIGHT","SOCKET","SWITCH","POWER"}.Contains(m.kind))throw new Exception("Dữ liệu MEPS không hợp lệ.");foreach(var s in new[]{m.code,m.name,m.level,m.function})if(s!=null&&(s.Length>150||s.Any(char.IsControl)))throw new Exception("Tên/mã quá dài hoặc chứa ký tự điều khiển.");if(string.IsNullOrWhiteSpace(m.code)||string.IsNullOrWhiteSpace(m.name))throw new Exception("Nhập mã và tên.");if(m.watts.HasValue&&(!Finite(m.watts.Value)||m.watts.Value<0||m.watts.Value>1e8))throw new Exception("Công suất phải là số W không âm; để trống nếu chưa biết.");}
  static double Cross(P a,P b,P p){return (b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x);}
  static bool On(P a,P b,P p){return Math.Abs(Cross(a,b,p))<1e-8&&p.x>=Math.Min(a.x,b.x)-1e-8&&p.x<=Math.Max(a.x,b.x)+1e-8&&p.y>=Math.Min(a.y,b.y)-1e-8&&p.y<=Math.Max(a.y,b.y)+1e-8;}
  public static double Area(P[] p){double sum=0;for(int i=0;i<p.Length;i++){P a=p[i],b=p[(i+1)%p.Length];sum+=(a.x-p[0].x)*(b.y-p[0].y)-(b.x-p[0].x)*(a.y-p[0].y);}return Math.Abs(sum)*.5;}
  public static void Polygon(P[] p){if(p==null||p.Length<3||p.Length>1000||p.Any(v=>v==null||!Finite(v.x)||!Finite(v.y)))throw new Exception("Đường bao cần 3–1000 đỉnh hợp lệ.");for(int i=0;i<p.Length;i++){P a=p[i],b=p[(i+1)%p.Length];if(Math.Abs(a.x-b.x)+Math.Abs(a.y-b.y)<1e-9)throw new Exception("Đường bao có cạnh bằng 0.");for(int j=i+1;j<p.Length;j++){if(j==i+1||i==0&&j==p.Length-1)continue;P c=p[j],d=p[(j+1)%p.Length];if(Cross(a,b,c)*Cross(a,b,d)<0&&Cross(c,d,a)*Cross(c,d,b)<0||On(a,b,c)||On(a,b,d)||On(c,d,a)||On(c,d,b))throw new Exception("Đường bao tự giao/chạm; sửa đường bao trước.");}}if(Area(p)<1e-10)throw new Exception("Đường bao không có diện tích.");}
  // -1 boundary, 0 outside, 1 inside: boundary needs an explicit placement correction.
  public static int Locate(P[] poly,P point){bool inside=false;for(int i=0,j=poly.Length-1;i<poly.Length;j=i++){var a=poly[j];var b=poly[i];if(On(a,b,point))return -1;if((a.y>point.y)!=(b.y>point.y)&&point.x<(b.x-a.x)*(point.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside?1:0;}
  public static P[] Grid(P[] p,int rows,int cols){Polygon(p);if(rows<1||cols<1||rows*cols>200)throw new Exception("Lưới 1–200 điểm/lần.");double x=p.Min(v=>v.x),y=p.Min(v=>v.y),w=p.Max(v=>v.x)-x,h=p.Max(v=>v.y)-y;var points=new List<P>();for(int r=0;r<rows;r++)for(int c=0;c<cols;c++){var v=new P(x+w*(c+.5)/cols,y+h*(r+.5)/rows);if(Locate(p,v)==1)points.Add(v);}return points.ToArray();}
  public static void Reconcile(Snapshot s){foreach(var d in s.devices){var hits=s.rooms.Where(r=>r.polygon!=null&&Locate(r.polygon,d.point)!=0).ToArray();d.Room=hits.Length==1&&Locate(hits[0].polygon,d.point)==1?hits[0].Code:"";d.Level=d.Room!=""?hits[0].Level:"";d.Issue=d.Room==""?(hits.Length==0?"Ngoài phòng":"Biên phòng/chồng vùng — cần kiểm tra"):"";if(!d.Watts.HasValue&&d.Kind!="SWITCH")d.Issue+=(d.Issue==""?"":"; ")+"Chưa có công suất";if(d.Issue!="")s.issues.Add(d.Code+": "+d.Issue);}foreach(var r in s.rooms){if(s.rooms.Count(x=>string.Equals(x.Code,r.Code,StringComparison.OrdinalIgnoreCase))>1){r.Watts=null;r.Issue="Trùng mã phòng — chưa tổng hợp tải";continue;}var list=s.devices.Where(d=>d.Room==r.Code).ToArray();int missing=list.Count(d=>!d.Watts.HasValue&&d.Kind!="SWITCH");double known=list.Where(d=>d.Watts.HasValue).Sum(d=>d.Watts.Value);r.Watts=missing==0?(double?)known:null;r.Issue=list.Length+" thiết bị; đã khai báo "+known.ToString(CultureInfo.InvariantCulture)+" W; "+missing+" chưa nhập công suất";}foreach(var g in s.rooms.Concat(s.devices).GroupBy(r=>r.Id).Where(g=>g.Count()>1))s.issues.Add("Trùng ID do COPY: "+string.Join(", ",g.Select(x=>x.Handle)));foreach(var g in s.rooms.Concat(s.devices).GroupBy(r=>r.Code,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1))s.issues.Add("Trùng mã: "+g.Key);}
  static void Entry(ZipArchive z,string name,Action<XmlWriter> action){using(var stream=z.CreateEntry(name).Open())using(var w=XmlWriter.Create(stream,new XmlWriterSettings{Encoding=new System.Text.UTF8Encoding(false)})){action(w);}}
  const string Ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
  static void Sheet(ZipArchive z,string path,IEnumerable<object[]> rows){Entry(z,path,w=>{w.WriteStartElement("worksheet",Ns);w.WriteStartElement("sheetData",Ns);int index=0;foreach(var cells in rows){w.WriteStartElement("row",Ns);w.WriteAttributeString("r",(++index).ToString());foreach(var cell in cells){w.WriteStartElement("c",Ns);if(cell is double||cell is int){w.WriteElementString("v",Ns,Convert.ToString(cell,CultureInfo.InvariantCulture));}else{w.WriteAttributeString("t","inlineStr");w.WriteStartElement("is",Ns);w.WriteElementString("t",Ns,Convert.ToString(cell,CultureInfo.InvariantCulture)??"");w.WriteEndElement();}w.WriteEndElement();}w.WriteEndElement();}w.WriteEndElement();w.WriteEndElement();});}
  public static void Export(string path,Snapshot s){if(!string.Equals(Path.GetExtension(path),".xlsx",StringComparison.OrdinalIgnoreCase))throw new Exception("Chọn file .xlsx.");string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var f=new FileStream(temp,FileMode.CreateNew))using(var z=new ZipArchive(f,ZipArchiveMode.Create)){
   Entry(z,"[Content_Types].xml",w=>{string ns="http://schemas.openxmlformats.org/package/2006/content-types";w.WriteStartElement("Types",ns);foreach(var pair in new[]{new[]{"rels","application/vnd.openxmlformats-package.relationships+xml"},new[]{"xml","application/xml"}}){w.WriteStartElement("Default",ns);w.WriteAttributeString("Extension",pair[0]);w.WriteAttributeString("ContentType",pair[1]);w.WriteEndElement();}for(int i=0;i<4;i++){w.WriteStartElement("Override",ns);w.WriteAttributeString("PartName",i==0?"/xl/workbook.xml":"/xl/worksheets/sheet"+i+".xml");w.WriteAttributeString("ContentType",i==0?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml":"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml");w.WriteEndElement();}w.WriteEndElement();});
   Entry(z,"_rels/.rels",w=>Relations(w,new[]{"xl/workbook.xml"},true));Entry(z,"xl/_rels/workbook.xml.rels",w=>Relations(w,new[]{"worksheets/sheet1.xml","worksheets/sheet2.xml","worksheets/sheet3.xml"},false));
   Entry(z,"xl/workbook.xml",w=>{w.WriteStartElement("workbook",Ns);w.WriteStartElement("sheets",Ns);int i=0;foreach(string name in new[]{"PHONG","THIET_BI","CANH_BAO"}){w.WriteStartElement("sheet",Ns);w.WriteAttributeString("name",name);w.WriteAttributeString("sheetId",(++i).ToString());w.WriteAttributeString("r","id","http://schemas.openxmlformats.org/officeDocument/2006/relationships","rId"+i);w.WriteEndElement();}w.WriteEndElement();w.WriteEndElement();});
   Sheet(z,"xl/worksheets/sheet1.xml",new[]{new object[]{"ID","Handle","Ma phong","Ten phong","Tang","Cong nang","Dien tich m2","Tong W (trong = chua du)","Ghi chu"}}.Concat(s.rooms.Select(r=>new object[]{r.Id,r.Handle,r.Code,r.Name,r.Level,r.Kind,r.AreaM2,r.Watts,r.Issue})));
   Sheet(z,"xl/worksheets/sheet2.xml",new[]{new object[]{"ID","Handle","Ma thiet bi","Ten","Loai","Phong","Tang","Cong suat W (trong = chua biet)","Canh bao"}}.Concat(s.devices.Select(r=>new object[]{r.Id,r.Handle,r.Code,r.Name,r.Kind,r.Room,r.Level,r.Watts,r.Issue})));
   Sheet(z,"xl/worksheets/sheet3.xml",new[]{new object[]{"Ghi chu / Canh bao"},new object[]{"BO TRI SO BO — CHUA KIEM CHUNG THIET KE DIEN / CHIEU SANG"}}.Concat(s.issues.Select(x=>new object[]{x})));
  }if(File.Exists(path))File.Replace(temp,path,path+"."+DateTime.UtcNow.ToString("yyyyMMddHHmmssfff")+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  static void Relations(XmlWriter w,string[] paths,bool root){string ns="http://schemas.openxmlformats.org/package/2006/relationships";w.WriteStartElement("Relationships",ns);for(int i=0;i<paths.Length;i++){w.WriteStartElement("Relationship",ns);w.WriteAttributeString("Id","rId"+(i+1));w.WriteAttributeString("Type","http://schemas.openxmlformats.org/officeDocument/2006/relationships/"+(root?"officeDocument":"worksheet"));w.WriteAttributeString("Target",paths[i]);w.WriteEndElement();}w.WriteEndElement();}
 }
}
